export function describeDay(input: Date | string | number, now: Date = new Date()): string {
  const moment = new Date(input);
  if (Number.isNaN(moment.getTime())) return "";
  const sameYear = moment.getUTCFullYear() === now.getUTCFullYear();
  const formatter = new Intl.DateTimeFormat("en-US", {
    day: "numeric",
    month: "short",
    year: sameYear ? undefined : "numeric",
    timeZone: "UTC",
  });
  return formatter.format(moment);
}

export function timeSinceLabel(then: number, reference: number): string {
  const elapsedDays = Math.max(0, Math.floor((reference - then) / 86_400_000));
  const steps: [string, number][] = [
    ["year", 365],
    ["month", 30],
    ["day", 1],
  ];
  for (const [unit, size] of steps) {
    const count = Math.floor(elapsedDays / size);
    if (count >= 1) return `${count} ${unit}${count === 1 ? "" : "s"} ago`;
  }
  return "today";
}

export function looksNavigable(candidate: unknown): boolean {
  if (typeof candidate !== "string") return false;
  const text = candidate.trim();
  if (text.length === 0) return false;
  let parsed: URL;
  try {
    parsed = new URL(text);
  } catch {
    return false;
  }
  const allowed = ["http:", "https:", "mailto:"];
  return allowed.indexOf(parsed.protocol) !== -1;
}

export function escapeForXml(value: string): string {
  const table: Record<string, string> = {
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    '"': "&quot;",
    "'": "&apos;",
  };
  let out = "";
  for (const ch of value) {
    out += table[ch] ?? ch;
  }
  return out;
}

export function dedupeById<T extends { id: string }>(list: T[]): T[] {
  const kept = new Map<string, T>();
  for (const entry of list) {
    if (!kept.has(entry.id)) kept.set(entry.id, entry);
  }
  return [...kept.values()];
}

export function localZoneName(): string {
  try {
    const zone = Intl.DateTimeFormat().resolvedOptions().timeZone;
    return zone ? zone : "UTC";
  } catch {
    return "UTC";
  }
}
